<template>
  <q-page class="table-explanation-page" data-test="table-explanation-page">
    <div class="table-explanation-head row items-center no-wrap">
      <q-btn
        flat
        dense
        round
        icon="arrow_back"
        :title="$t('ai_explain_back_to_document')"
        data-test="table-explanation-back"
        @click="back"
      />
      <div class="q-ml-sm">
        <h1 class="text-h6 q-my-none">{{ $t('ai_explain_title') }}</h1>
        <p class="table-explanation-sub q-mb-none" v-if="explanation">
          {{ explanation.filename || explanation.doc_id }} ·
          {{ explanation.table_name }}
        </p>
      </div>
      <q-space />
      <q-btn
        v-if="explanation"
        flat
        dense
        no-caps
        icon="refresh"
        :label="$t('ai_explain_reload')"
        data-test="table-explanation-reload"
        @click="load"
      />
    </div>

    <div v-if="loading" class="q-pa-md" data-test="table-explanation-loading">
      <q-spinner size="sm" class="q-mr-sm" />{{ $t('ai_explain_loading') }}
    </div>

    <div
      v-else-if="forbidden"
      class="q-pa-md table-explanation-forbidden"
      :data-test="`table-explanation-forbidden-${forbidden}`"
    >
      <q-icon name="lock" size="28px" color="warning" class="q-mb-sm" />
      <!--
        module_off: the organisation has no licence for the module.
        no_access: it has the licence, this user is not enabled yet.
      -->
      <p class="text-subtitle1 text-weight-medium q-mb-xs">
        {{
          forbidden === 'module_off'
            ? $t('ai_explain_license_title')
            : $t('ai_explain_user_access_title')
        }}
      </p>
      <p class="q-mb-sm">
        {{
          forbidden === 'module_off'
            ? $t('ai_explain_license_required')
            : $t('ai_explain_user_access_required')
        }}
      </p>
      <q-btn
        v-if="forbidden === 'module_off'"
        no-caps
        color="primary"
        icon="tune"
        :label="$t('ai_explain_open_modules')"
        data-test="table-explanation-open-modules"
        @click="$router.push(MODULES_ROUTE)"
      />
    </div>

    <div v-else-if="error" class="q-pa-md" data-test="table-explanation-error">
      {{ $t('ai_explain_failed') }}
      <span class="table-explanation-sub">{{ error }}</span>
    </div>

    <div v-else-if="explanation" class="table-explanation-grid">
      <!-- left: the document, page by page — the reader sees the raw columns next to the picture they came from -->
      <aside
        class="table-explanation-preview"
        data-test="table-explanation-preview"
      >
        <div class="row items-center no-wrap q-mb-sm">
          <b>{{ $t('ai_explain_preview') }}</b>
          <q-space />
          <q-btn
            flat
            dense
            round
            icon="chevron_left"
            :disable="page <= 1"
            data-test="table-explanation-prev-page"
            @click="page = Math.max(1, page - 1)"
          />
          <span
            class="table-explanation-sub"
            data-test="table-explanation-page-no"
            >{{ page }} / {{ pageCount }}</span
          >
          <q-btn
            flat
            dense
            round
            icon="chevron_right"
            :disable="page >= pageCount"
            data-test="table-explanation-next-page"
            @click="page = Math.min(pageCount, page + 1)"
          />
        </div>
        <img
          v-if="pageImageUrl"
          :src="pageImageUrl"
          :alt="`${$t('ai_explain_preview')} ${page}`"
          class="table-explanation-page-image"
          data-test="table-explanation-page-image"
        />
      </aside>

      <!-- right: the explanation, full height, nothing folded away -->
      <section class="table-explanation-content">
        <AITableExplanationContent
          :explanation="explanation"
          :stages="stages"
          :advice="advice"
          :advice-loading="adviceLoading"
        />
      </section>
    </div>
  </q-page>
</template>

<script lang="ts">
/**
 * The AI-table explanation as its own page (DOCB-14569).
 *
 * Same content as the "Show" dialog, but with the document preview beside
 * it: raw columns on the right, the page they were read from on the left,
 * and enough room for every section without a scrolling popup. Route
 * `table-explanation` (`:id` = document, `?table=` = table name).
 *
 * Three reads, in this order: the explanation (fast, blocks the page), the
 * pipeline stages (may fail on its own), then the KI-Advisor block in a
 * second request (8–15 s) — the page is readable long before it arrives.
 */
import { defineComponent } from 'vue';
import AITableExplanationContent from 'src/components/document/AITableExplanationContent.vue';
import {
  MODULES_ROUTE,
  forbiddenReason,
  type ForbiddenReason,
} from 'src/components/document/tableExplanationAccess';
import { DOC2API_URL } from 'src/pages/APIs';
import { useImageAuth } from 'src/composables/useImageAuth';
import {
  pipelineExplanationService,
  tableExplanationService,
} from 'src/services';
import type { PipelineStage } from 'src/services/analytics/PipelineExplanationService';
import type {
  TableExplanation,
  TableExplanationAdvice,
} from 'src/services/analytics/TableExplanationService';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';

export default defineComponent({
  name: 'TableExplanationPage',
  components: { AITableExplanationContent },
  setup() {
    const { tokenQueryParam, refreshTokenParam } = useImageAuth();
    return { tokenQueryParam, refreshTokenParam, MODULES_ROUTE };
  },
  data() {
    return {
      loading: false,
      error: '',
      forbidden: '' as ForbiddenReason | '',
      explanation: null as TableExplanation | null,
      stages: [] as PipelineStage[],
      advice: null as TableExplanationAdvice | null,
      adviceLoading: false,
      page: 1,
    };
  },
  computed: {
    docId(): string {
      return String(this.$route.params.id || '');
    },
    tableName(): string | null {
      const table = this.$route.query.table;
      return typeof table === 'string' && table ? table : null;
    },
    pageCount(): number {
      const pages = Number(this.explanation?.steps?.document?.pages || 0);
      return pages > 0 ? pages : 1;
    },
    /** `/resource/image/{doc}/{page}.png` with the token the image route expects. */
    pageImageUrl(): string {
      if (!this.docId || !this.tokenQueryParam) return '';
      return `${DOC2API_URL}/resource/image/${encodeURIComponent(this.docId)}/${this.page}.png?${this.tokenQueryParam}`;
    },
  },
  watch: {
    '$route.params.id'() {
      void this.load();
    },
    '$route.query.table'() {
      void this.load();
    },
  },
  mounted() {
    void this.load();
  },
  methods: {
    async load() {
      if (!this.docId) return;
      const docId = this.docId;
      const tableName = this.tableName;
      this.loading = true;
      this.error = '';
      this.forbidden = '';
      this.explanation = null;
      this.stages = [];
      this.advice = null;
      this.adviceLoading = false;
      this.page = 1;
      try {
        const [explanation, pipeline] = await Promise.all([
          tableExplanationService.getDocumentTableExplanation(docId, tableName),
          pipelineExplanationService
            .getDocumentPipeline(docId)
            .catch(() => null),
        ]);
        // the route may have moved on while we were waiting
        if (this.docId !== docId) return;
        this.explanation = explanation;
        this.stages = pipeline?.stages || [];
      } catch (error) {
        // 403 = the Analytics Dashboard module is off for this org / user —
        // not a failure of the explanation, a door to open in the modules
        const reason = forbiddenReason(error);
        if (reason) {
          this.forbidden = reason;
        } else {
          this.error = ApiExceptions.getErrorMessage(error as dynamicObj);
        }
      } finally {
        this.loading = false;
      }
      if (this.explanation) void this.loadAdvice(docId, tableName);
    },
    async loadAdvice(docId: string, tableName: string | null) {
      this.adviceLoading = true;
      try {
        const withAdvice =
          await tableExplanationService.getDocumentTableExplanation(
            docId,
            tableName,
            { includeRecommendation: true },
          );
        if (this.docId === docId) this.advice = withAdvice.advice || null;
      } catch {
        if (this.docId === docId) this.advice = null;
      } finally {
        // a request for a document we have left must not touch this page's state
        if (this.docId === docId) this.adviceLoading = false;
      }
    },
    back() {
      if (window.history.length > 1) {
        this.$router.back();
      } else {
        void this.$router.push('/dashboard');
      }
    },
  },
});
</script>

